import json
from itertools import product

U = range(3)
subsets = [frozenset(i for i in U if m >> i & 1) for m in range(8)]

def some_not(X, Y):      # some X are not Y
    return len(X - Y) > 0

def not_all(X, Y):       # not all X are Y
    return not (X <= Y)

def valid(prem, concl):
    return all(concl(X, Y) for X, Y in product(subsets, subsets) if prem(X, Y))

# Original: Some G are not C  =>  Not all C are G (terms swapped)
orig = valid(lambda G, C: some_not(G, C), lambda G, C: not_all(C, G))

forms = {
    # A: Some H are not P => some P are not H (terms swapped, same form as original)
    "A": valid(lambda H, P: some_not(H, P), lambda H, P: some_not(P, H)),
    # B: Some S are not P => not all S are P (same terms, equivalent statement)
    "B": valid(lambda S, P: some_not(S, P), lambda S, P: not_all(S, P)),
    # C: some good motives not good effects => some good results not from good motives (swapped)
    "C": valid(lambda M, E: some_not(M, E), lambda M, E: some_not(E, M)),
    # D: Some southerners are not Cantonese => not all Cantonese are southerners (swapped)
    "D": valid(lambda S, C: some_not(S, C), lambda S, C: not_all(C, S)),
}

# The option that does not share the original's (invalid, term-swapping) form is the answer.
different = [k for k, v in forms.items() if v != orig]

if len(different) == 1:
    print(json.dumps({
        "final_answer": different[0],
        "evidence": {"original_form_valid": orig, "option_forms_valid": forms}
    }))
else:
    print("UNSUPPORTED")
